#!/usr/bin/env node
/**
 * Writes src/constants/usLocations.ts: every U.S. state that has cities, and its city names.
 *
 *   node scripts/genUsLocations.js
 *
 * The app used to import country-state-city directly, which bundles every city in the world as
 * one 8 MB array literal. iPhone Safari runs out of stack compiling it ("Maximum call stack size
 * exceeded"). The generated file is ~250 KB, and each state's cities are one "|"-joined string,
 * so there are no huge literals left for the browser to compile.
 */
const fs = require('fs');
const path = require('path');
const { City, State } = require('country-state-city');

const COUNTRY_CODE = 'US';

const citiesByState = {};
for (const c of City.getCitiesOfCountry(COUNTRY_CODE) ?? []) {
  (citiesByState[c.stateCode] ??= new Set()).add(c.name);
}

const states = State.getStatesOfCountry(COUNTRY_CODE)
  .filter((s) => citiesByState[s.isoCode])
  .map((s) => ({ code: s.isoCode, name: s.name }));

const lines = [
  '// Generated by scripts/genUsLocations.js from country-state-city. Do not edit by hand.',
  '',
  '/** U.S. states that have at least one city, in country-state-city order. */',
  `export const US_STATES: { code: string; name: string }[] = ${JSON.stringify(states)};`,
  '',
  '/** City names for each state code, joined with "|". Use citiesOfState() instead. */',
  'const CITIES: Record<string, string> = {',
  ...states.map((s) => `  ${JSON.stringify(s.code)}: ${JSON.stringify([...citiesByState[s.code]].join('|'))},`),
  '};',
  '',
  'export function citiesOfState(code: string): string[] {',
  "  return CITIES[code]?.split('|') ?? [];",
  '}',
  '',
];

const out = path.join(__dirname, '..', 'src', 'constants', 'usLocations.ts');
fs.writeFileSync(out, lines.join('\n'));
console.log(`Wrote ${out}: ${states.length} states`);
